// minimal-rag.js — the same pipeline with this course's own core modules
import { chunk } from '/assets/js/core/chunker.js';
import { loadModel, embed, embedBatch } from '/assets/js/core/embed.js';
import { VectorStore } from '/assets/js/core/vectorstore.js';
import { generate, ragPrompt } from '/assets/js/core/llm.js';
import { hitAtK, reciprocalRank } from '/assets/js/core/metrics.js';

// every setting is written down: nothing comes from a hidden default
const CONFIG = {
  strategy: 'recursive', size: 150, overlap: 20, k: 3,
  model: 'Xenova/multilingual-e5-small', provider: 'openai', temperature: 0,
};

const corpus = await (await fetch('/assets/data/corpus/corpus.json')).json();
const golden = await (await fetch('/assets/data/golden/golden.json')).json();
const chunks = corpus.documents.flatMap((doc) =>
  chunk(doc.text, { strategy: CONFIG.strategy, size: CONFIG.size, overlap: CONFIG.overlap })
    .map((c) => ({ ...c, id: `${doc.id}#${c.index}`, docId: doc.id })));
await loadModel(CONFIG.model); // e5 'passage: ' / 'query: ' prefixes are added in embed.js
const vectors = await embedBatch(chunks.map((c) => c.text), { role: 'passage' });
const store = new VectorStore(); // flat cosine, vectors L2-normalized on add
chunks.forEach((c, i) => store.add(c.id, vectors[i], { docId: c.docId, text: c.text }));
async function retrieve(question, k = CONFIG.k) {
  const q = await embed(question, { role: 'query' });
  return store.search(q, k); // [{ id, score, meta }]
}
function buildPrompt(question, hits) {
  return ragPrompt(question, hits.map((h) => ({ text: h.meta.text })));
}
async function answer(question) {
  const hits = await retrieve(question);
  const { system, messages } = buildPrompt(question, hits);
  const { text } = await generate({
    provider: CONFIG.provider, system, messages, temperature: CONFIG.temperature,
  });
  return { text, sources: hits.map((h) => h.id) };
}
console.log(await answer('RRF에서 k 값은 보통 얼마를 쓰나?'));
let hit = 0, mrr = 0;
for (const item of golden.items) {
  const ids = (await retrieve(item.question)).map((h) => h.id);
  const relevant = chunks
    .filter((c) => item.evidence.some((e) => c.text.includes(e.quote)))
    .map((c) => c.id);
  hit += hitAtK(ids, relevant, CONFIG.k);
  mrr += reciprocalRank(ids, relevant);
}
const n = golden.items.length;
console.log(`hit@${CONFIG.k}=${(hit / n).toFixed(3)}  MRR=${(mrr / n).toFixed(3)}`);
